<script setup lang="ts">
/**
 * A date range *field* with two segmented entries and a calendar popup (`design/components/date-range-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/popover'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentDateRange,
  agentMember,
  anchorProps,
  calendarDateOf,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  eraseSegment,
  fieldSegments,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button.vue'
import DateRangePickerRangeCalendar from './DateRangePickerRangeCalendar.vue'
import type { CalendarDate, CalendarMessages } from './Calendar.vue'

export interface DateRange {
  start: CalendarDate
  end: CalendarDate
}

export type DateRangePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseRange: string
}

export interface DateRangePickerProps {
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * DatePicker's clear button: reports `onChange(null)` and resets both groups to placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: DateRange | null
  disabled?: boolean
  endName?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Also orders the segments and picks the separators.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DateRangePickerMessages
  /**
   * react-aria's validation, forwarded. A typed date outside the bounds marks the field invalid.
   * React Aria marks a reversed pair (end before start) invalid on both halves.
   */
  minValue?: CalendarDate
  /**
   * Same as DatePicker (`date-picker.md`, the conventions' sheet presentation). `'auto'` shows
   * the popup as a sheet below `30rem`, with RangeCalendar unchanged inside it. `'popover'`
   * keeps the popover at every width. The anchored-range keyboard model, the two-stage Escape
   * and the focus hand-off work the same after re-anchoring.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Two hidden inputs serialize ISO-8601, as DatePicker does, once per end, because one `name`
   * cannot carry two values.
   */
  startName?: string
  /**
   * Both ends or `null`. A half-entered range is never reported. `onChange` fires when the
   * second end is committed, and clearing reports `null`. Uses `CalendarDate`, never `Date`
   * (Calendar's law).
   */
  value?: DateRange | null
}

defineOptions({ name: 'DateRangePicker', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<DateRangePickerProps>(), {
  ariaRequired: undefined,
  clearable: false,
  defaultOpen: undefined,
  disabled: false,
  invalid: false,
  isDateUnavailable: undefined,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{ change: [value: DateRange | null] }>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const startDraft = ref(
  dateFieldDraft((props.value !== undefined ? props.value : props.defaultValue)?.start, {
    locale: props.locale ?? browserLanguage.value ?? 'en-US',
    parts: ['year', 'month', 'day'] as const,
  }),
)
const endDraft = ref(
  dateFieldDraft((props.value !== undefined ? props.value : props.defaultValue)?.end, {
    locale: props.locale ?? browserLanguage.value ?? 'en-US',
    parts: ['year', 'month', 'day'] as const,
  }),
)
const typed = ref('')
const reported = ref(
  ((given) =>
    given === null || given === undefined
      ? ''
      : `${given.start.toString()}/${given.end.toString()}`)(
    props.value !== undefined ? props.value : props.defaultValue,
  ),
)
const anchored = ref(false)
const anchor = useTemplateRef<HTMLElement>('anchor')
const field = useTemplateRef<HTMLElement>('field')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const say = computed(
  () =>
    props.messages ?? {
      previousMonth: 'Previous month',
      nextMonth: 'Next month',
      showCalendar: 'Show calendar',
      clear: 'Clear',
      chooseRange: 'Choose a date range',
    },
)
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const fieldOptions = computed(() => ({
  locale: language.value,
  parts: ['year', 'month', 'day'] as const,
}))
const startSegments = computed(() => fieldSegments(startDraft.value, fieldOptions.value))
const endSegments = computed(() => fieldSegments(endDraft.value, fieldOptions.value))
const rangeOf = computed(
  () =>
    (
      start: ReturnType<typeof dateFieldDraft>,
      end: ReturnType<typeof dateFieldDraft>,
    ): DateRange | null => {
      const from = dateFieldValue(start, fieldOptions.value)
      const to = dateFieldValue(end, fieldOptions.value)
      return from === null || to === null
        ? null
        : { start: calendarDateOf(from), end: calendarDateOf(to) }
    },
)
const range = computed(() => rangeOf.value(startDraft.value, endDraft.value))
const bounds = computed(() => ({
  min: props.minValue,
  max: props.maxValue,
  unavailable: props.isDateUnavailable,
}))
const fieldInvalid = computed(
  () =>
    props.invalid ||
    dateOutOfBounds(dateFieldValue(startDraft.value, fieldOptions.value), bounds.value) ||
    dateOutOfBounds(dateFieldValue(endDraft.value, fieldOptions.value), bounds.value) ||
    (range.value !== null && range.value.end.compare(range.value.start) < 0),
)
const showClear = computed(() => props.clearable && range.value !== null && !props.disabled)
const report = computed(
  () =>
    (start: ReturnType<typeof dateFieldDraft>, end: ReturnType<typeof dateFieldDraft>): void => {
      startDraft.value = start
      endDraft.value = end
      const after = rangeOf.value(start, end)
      const text = after === null ? '' : `${after.start.toString()}/${after.end.toString()}`
      if (text !== reported.value) {
        reported.value = text
        emit('change', after)
      }
    },
)
const startCommit = computed(
  () =>
    (next: ReturnType<typeof dateFieldDraft>): void =>
      report.value(next, endDraft.value),
)
const endCommit = computed(
  () =>
    (next: ReturnType<typeof dateFieldDraft>): void =>
      report.value(startDraft.value, next),
)
const clear = computed(() => (): void => {
  report.value({}, {})
  field.value?.querySelector<HTMLElement>('[data-segment]')?.focus()
})
const segmentName = computed(() => (type: string): string => {
  try {
    return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = computed(() => (from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const startInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
      event.preventDefault()
      if (segment.type === 'literal' || !!props.disabled) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoSegment(
          startDraft.value,
          segment.type,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        startCommit.value(next.draft)
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const endInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
      event.preventDefault()
      if (segment.type === 'literal' || !!props.disabled) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoSegment(
          endDraft.value,
          segment.type,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        endCommit.value(next.draft)
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const documentDirection = useDirection(() => field.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen,
    modal: sheeting.value,
    positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
    ids: props.id === undefined ? undefined : { anchor: props.id },
    initialFocusEl: () =>
      (sheetPanel.value ?? panel.value)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
    onEscapeKeyDown: (details) => {
      anchored.value && details.preventDefault()
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const choose = computed(() => (next: DateRange): void => {
  report.value(
    dateFieldDraft(next.start, fieldOptions.value),
    dateFieldDraft(next.end, fieldOptions.value),
  )
  api.value.setOpen(false)
})
const startKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
      if (segment.type === 'literal') return
      if (event.altKey && event.key === 'ArrowDown') {
        event.preventDefault()
        if (!props.disabled) api.value.setOpen(true)
        return
      }
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        typed.value = ''
        moveSegment.value(
          event.currentTarget,
          (event.key === 'ArrowRight') ===
            (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
            ? 1
            : -1,
        )
        return
      }
      if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
      const editable = !props.disabled
      if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault()
        typed.value = ''
        if (editable)
          startCommit.value(
            stepSegment(
              startDraft.value,
              segment.type,
              event.key === 'ArrowUp' ? 1 : -1,
              fieldOptions.value,
            ),
          )
        return
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        typed.value = ''
        if (!editable) return
        if (startDraft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
        else startCommit.value(eraseSegment(startDraft.value, segment.type, fieldOptions.value))
        return
      }
      if (event.key.length !== 1) return
      event.preventDefault()
      if (editable)
        ((key: string): void => {
          const next = typeIntoSegment(
            startDraft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          startCommit.value(next.draft)
          if (next.advance) moveSegment.value(event.currentTarget, 1)
        })(event.key)
    },
)
const endKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
      if (segment.type === 'literal') return
      if (event.altKey && event.key === 'ArrowDown') {
        event.preventDefault()
        if (!props.disabled) api.value.setOpen(true)
        return
      }
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        typed.value = ''
        moveSegment.value(
          event.currentTarget,
          (event.key === 'ArrowRight') ===
            (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
            ? 1
            : -1,
        )
        return
      }
      if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
      const editable = !props.disabled
      if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault()
        typed.value = ''
        if (editable)
          endCommit.value(
            stepSegment(
              endDraft.value,
              segment.type,
              event.key === 'ArrowUp' ? 1 : -1,
              fieldOptions.value,
            ),
          )
        return
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        typed.value = ''
        if (!editable) return
        if (endDraft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
        else endCommit.value(eraseSegment(endDraft.value, segment.type, fieldOptions.value))
        return
      }
      if (event.key.length !== 1) return
      event.preventDefault()
      if (editable)
        ((key: string): void => {
          const next = typeIntoSegment(
            endDraft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          endCommit.value(next.draft)
          if (next.advance) moveSegment.value(event.currentTarget, 1)
        })(event.key)
    },
)
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  browserLanguage.value = globalThis.navigator?.language
}
onMounted(effect1)
const effect2 = () => {
  syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
}
onMounted(effect2)
watch(() => api.value.open, effect2, { flush: 'post' })
const effect3 = () => {
  props.value !== undefined &&
    (props.value !== null || range.value !== null) &&
    ((startDraft.value = dateFieldDraft(props.value?.start, fieldOptions.value)),
    (endDraft.value = dateFieldDraft(props.value?.end, fieldOptions.value)),
    (reported.value = ((given) =>
      given === null || given === undefined
        ? ''
        : `${given.start.toString()}/${given.end.toString()}`)(props.value)))
}
watch(() => props.value, effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'DateRangePicker',
    element: () => field.value,
    state: () => ({
      value:
        range.value === null ? '' : `${range.value.start.toString()}/${range.value.end.toString()}`,
      open: api.value.open,
      disabled: props.disabled,
      invalid: fieldInvalid.value,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          ((next) =>
            report.value(
              dateFieldDraft(next.start, fieldOptions.value),
              dateFieldDraft(next.end, fieldOptions.value),
            ))(agentDateRange(value, bounds.value)),
      },
      clear: () => report.value({}, {}),
      open: () => api.value.setOpen(true),
      close: () => api.value.setOpen(false),
    },
    withholds: () => [field.value, sheetPanel.value ?? panel.value],
  })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <div
    ref="field"
    v-bind="api.getAnchorProps()"
    :class="styles.field"
    role="group"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-disabled="disabled ? 'true' : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="fieldInvalid ? '' : undefined"
    :data-state="api.open ? 'open' : 'closed'"
    data-member="date-range-picker"
  >
    <!-- segments -->
    <div :class="styles.segments" :data-size="size">
      <template v-for="(segment, at) in startSegments" :key="`start-${segment.type}-${at}`">
        <!-- separator -->
        <span v-if="segment.type === 'literal'" :class="styles.separator" aria-hidden="true">
          {{ segment.text }}
        </span>
        <!-- segment -->
        <div
          v-else
          :class="styles.segment"
          role="spinbutton"
          :id="`${uid}-start-${segment.type}`"
          :aria-label="`${'Start date'}, ${segmentName(segment.type)}`"
          :aria-labelledby="
            ariaLabelledby ? `${ariaLabelledby} ${uid}-start-${segment.type}` : undefined
          "
          :aria-describedby="ariaDescribedby"
          :aria-valuenow="segment.placeholder ? undefined : segment.value"
          :aria-valuemin="segment.min"
          :aria-valuemax="segment.max"
          :aria-valuetext="segment.placeholder ? 'Empty' : segment.text"
          :aria-required="ariaRequired ? 'true' : undefined"
          :aria-disabled="disabled ? 'true' : undefined"
          :aria-invalid="fieldInvalid ? 'true' : undefined"
          :contenteditable="!disabled ? 'true' : undefined"
          :inputmode="segment.type === 'dayPeriod' ? undefined : 'numeric'"
          spellcheck="false"
          :tabindex="disabled ? undefined : '0'"
          :data-segment="segment.type"
          :data-placeholder="segment.placeholder ? '' : undefined"
          :data-disabled="disabled ? '' : undefined"
          @focus="typed = ''"
          @keydown="startKeys($event, segment)"
          @beforeinput="startInput($event, segment)"
        >
          {{ segment.text }}
        </div>
      </template>
    </div>
    <!-- dash -->
    <span :class="styles.dash" aria-hidden="true"> – </span>
    <!-- segments -->
    <div :class="styles.segments" :data-size="size">
      <template v-for="(segment, at) in endSegments" :key="`end-${segment.type}-${at}`">
        <!-- separator -->
        <span v-if="segment.type === 'literal'" :class="styles.separator" aria-hidden="true">
          {{ segment.text }}
        </span>
        <!-- segment -->
        <div
          v-else
          :class="styles.segment"
          role="spinbutton"
          :id="`${uid}-end-${segment.type}`"
          :aria-label="`${'End date'}, ${segmentName(segment.type)}`"
          :aria-labelledby="
            ariaLabelledby ? `${ariaLabelledby} ${uid}-end-${segment.type}` : undefined
          "
          :aria-describedby="ariaDescribedby"
          :aria-valuenow="segment.placeholder ? undefined : segment.value"
          :aria-valuemin="segment.min"
          :aria-valuemax="segment.max"
          :aria-valuetext="segment.placeholder ? 'Empty' : segment.text"
          :aria-required="ariaRequired ? 'true' : undefined"
          :aria-disabled="disabled ? 'true' : undefined"
          :aria-invalid="fieldInvalid ? 'true' : undefined"
          :contenteditable="!disabled ? 'true' : undefined"
          :inputmode="segment.type === 'dayPeriod' ? undefined : 'numeric'"
          spellcheck="false"
          :tabindex="disabled ? undefined : '0'"
          :data-segment="segment.type"
          :data-placeholder="segment.placeholder ? '' : undefined"
          :data-disabled="disabled ? '' : undefined"
          @focus="typed = ''"
          @keydown="endKeys($event, segment)"
          @beforeinput="endInput($event, segment)"
        >
          {{ segment.text }}
        </div>
      </template>
    </div>
    <span :class="styles.spacer" />
    <input
      v-if="startName !== undefined"
      type="hidden"
      :name="startName"
      :value="range?.start.toString() ?? ''"
      :disabled="disabled ? true : undefined"
    />
    <input
      v-if="endName !== undefined"
      type="hidden"
      :name="endName"
      :value="range?.end.toString() ?? ''"
      :disabled="disabled ? true : undefined"
    />
    <!-- clear -->
    <button
      v-if="showClear"
      :class="styles.clear"
      type="button"
      :aria-label="say.clear"
      @click="clear()"
    >
      <Icon name="clear" :size="size" />
    </button>
    <!-- trigger -->
    <span ref="anchor" v-bind="anchorProps(api.getTriggerProps())" :class="triggerAnchor.anchor">
      <Button
        variant="ghost"
        tone="neutral"
        :size="size"
        :iconOnly="true"
        icon="calendar"
        :label="say.showCalendar"
        :disabled="disabled"
      />
    </span>
  </div>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{ '--radix-popover-content-transform-origin': 'var(--transform-origin)' }"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="say.chooseRange"
        data-member="date-range-picker"
      >
        <DateRangePickerRangeCalendar
          :value="range"
          :minValue="minValue"
          :maxValue="maxValue"
          :isDateUnavailable="isDateUnavailable"
          :locale="language"
          :firstDayOfWeek="firstDayOfWeek"
          :disabled="disabled"
          :messages="say"
          :label="say.chooseRange"
          @commit="choose($event)"
          @anchorChange="anchored = $event"
        />
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        v-bind="api.getContentProps()"
        :class="sheet.panel"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="say.chooseRange"
        aria-modal="true"
        data-presentation="sheet"
      >
        <!-- sheetBody -->
        <div :class="styles.sheetBody" data-member="date-range-picker">
          <DateRangePickerRangeCalendar
            :value="range"
            :minValue="minValue"
            :maxValue="maxValue"
            :isDateUnavailable="isDateUnavailable"
            :locale="language"
            :firstDayOfWeek="firstDayOfWeek"
            :disabled="disabled"
            :messages="say"
            :label="say.chooseRange"
            @commit="choose($event)"
            @anchorChange="anchored = $event"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
